def list_workflows(instance_id, project_id=None, status=None, active=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    instances = _load("n8n_instances.json")
    workflows = _load("n8n_workflows.json")
    audit = _load("n8n_assets_and_audit.json")

    def _log(status_s, message=None):
        nonlocal audit
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        rid = "n8n_aud_" + secrets.token_hex(12).upper()
        audit.append({
            "id": rid,
            "instance_id": instance_id if isinstance(instance_id, str) else "n8n_ins_UNKNOWN",
            "asset_type": "audit_report",
            "external_id": None,
            "workflow_id": None,
            "project_id": None,
            "owner_principal_id": None,
            "name": "request_log",
            "key": None,
            "value_encrypted": None,
            "credential_type": None,
            "data_encrypted": None,
            "schema": None,
            "execution_status": None,
            "started_at": None,
            "stopped_at": None,
            "execution_data": None,
            "tag_id": None,
            "report": {
                "kind": "request_log",
                "endpoint": "list-workflows",
                "status": status_s,
                "message": message,
                "timestamp": now,
                "latency_ms": int(round((time.time() - t0) * 1000)),
            },
            "status": "active",
            "created_at": now,
            "updated_at": now
        })

    # Validate inputs
    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            raise ValueError("instance_id is invalid")
        if project_id is not None:
            if not isinstance(project_id, str) or not re.match(r"^n8n_prj_[0-9A-Z]{18,}$", project_id):
                raise ValueError("project_id is invalid")
        if status is not None:
            if not isinstance(status, str) or status not in ("draft", "active", "inactive", "deleted"):
                raise ValueError("status is invalid")
        if active is not None and not isinstance(active, bool):
            raise ValueError("active must be boolean")
        if search is not None and not isinstance(search, str):
            raise ValueError("search must be a string")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            raise ValueError("limit must be between 1 and 200")
        if cursor is not None and not isinstance(cursor, str):
            raise ValueError("cursor must be a string")
        if sort is None:
            sort = "updated_at"
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
            raise ValueError("sort must be one of created_at/updated_at/name")
        if order is None:
            order = "desc"
        if not isinstance(order, str) or order not in ("asc", "desc"):
            raise ValueError("order must be asc or desc")
    except ValueError as e:
        _log("error", str(e))
        _save("n8n_assets_and_audit.json", audit)
        return _err("VALIDATION_ERROR", str(e))

    # Enforce: must have active instance row for selected scope
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id and r.get("status") == "active":
            inst = r
            break
    if inst is None:
        _log("error", "No active instance for instance_id")
        _save("n8n_assets_and_audit.json", audit)
        return _err("UNAUTHORIZED", "No active n8n instance available for this request", instance_id=instance_id)

    # Filter: instance_id matches and status != 'deleted' (business rule)
    rows = []
    s_q = search.strip().lower() if isinstance(search, str) and search.strip() else None
    for w in workflows:
        if not isinstance(w, dict):
            continue
        if w.get("instance_id") != instance_id:
            continue
        if w.get("status") == "deleted":
            continue
        if project_id is not None and w.get("project_id") != project_id:
            continue
        if status is not None and w.get("status") != status:
            continue
        if active is not None and bool(w.get("active")) != active:
            continue
        if s_q is not None:
            nm = w.get("name") or ""
            if not isinstance(nm, str) or s_q not in nm.lower():
                continue
        rows.append(w)

    # Sort
    reverse = (order == "desc")

    def _key(w):
        if sort in ("created_at", "updated_at"):
            # ISO strings sort lexicographically for UTC "Z"
            v = w.get(sort) or ""
            return (v, w.get("id") or "")
        if sort == "name":
            v = (w.get("name") or "")
            if not isinstance(v, str):
                v = ""
            return (v.lower(), w.get("id") or "")
        return (w.get("updated_at") or "", w.get("id") or "")

    rows.sort(key=_key, reverse=reverse)

    # Cursor pagination: cursor is an offset encoded as "off_<int>"
    offset = 0
    if cursor:
        m = re.match(r"^off_(\d+)$", cursor)
        if not m:
            _log("error", "Invalid cursor")
            _save("n8n_assets_and_audit.json", audit)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        offset = int(m.group(1))

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = ("off_%d" % next_offset) if has_more else None

    # Summaries: do not strip required fields, but return typical list view (no heavy redaction rule stated)
    out = []
    for w in page:
        out.append({
            "id": w.get("id"),
            "instance_id": w.get("instance_id"),
            "project_id": w.get("project_id"),
            "name": w.get("name"),
            "active": w.get("active"),
            "status": w.get("status"),
            "created_by_principal_id": w.get("created_by_principal_id"),
            "updated_by_principal_id": w.get("updated_by_principal_id"),
            "created_at": w.get("created_at"),
            "updated_at": w.get("updated_at"),
        })

    _log("ok", "returned %d of %d" % (len(out), total))
    _save("n8n_assets_and_audit.json", audit)
    return {
        "workflows": out,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        },
        "sort": {"field": sort, "order": order}
    }

def get_workflow(instance_id, workflow_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get-workflow"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance_id_used=None, workflow_id_used=None, error_code=None):
        logs = _load("n8n_assets_and_audit.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        latency_ms = int((time.time() - _t0) * 1000)
        logs.append({
            "id": f"n8n_aud_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "instance_id": instance_id_used or instance_id or "n8n_ins_UNKNOWN",
            "asset_type": "audit_report",
            "external_id": None,
            "workflow_id": workflow_id_used,
            "project_id": None,
            "owner_principal_id": None,
            "name": "request_log",
            "key": endpoint,
            "value_encrypted": None,
            "credential_type": None,
            "data_encrypted": None,
            "schema": None,
            "execution_status": None,
            "started_at": ts,
            "stopped_at": ts,
            "execution_data": {
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms
            },
            "tag_id": None,
            "report": {"type": "request_log", "endpoint": endpoint, "status": status, "error_code": error_code, "latency_ms": latency_ms, "timestamp": ts},
            "status": "active",
            "created_at": ts,
            "updated_at": ts
        })
        _save("n8n_assets_and_audit.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            _log("error", instance_id_used=instance_id, workflow_id_used=workflow_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instance_id does not match required format", field="instance_id")
        if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
            _log("error", instance_id_used=instance_id, workflow_id_used=workflow_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workflow_id does not match required format", field="workflow_id")

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
        if not inst:
            _log("error", instance_id_used=instance_id, workflow_id_used=workflow_id, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
        if inst.get("status") != "active":
            _log("error", instance_id_used=instance_id, workflow_id_used=workflow_id, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active instance available for this request", instance_id=instance_id)

        workflows = _load("n8n_workflows.json")
        if not isinstance(workflows, list):
            workflows = []
        wf = next((w for w in workflows if isinstance(w, dict) and w.get("id") == workflow_id and w.get("instance_id") == instance_id and w.get("status") != "deleted"), None)
        if not wf:
            _log("error", instance_id_used=instance_id, workflow_id_used=workflow_id, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Workflow not found", instance_id=instance_id, workflow_id=workflow_id)

        _log("ok", instance_id_used=instance_id, workflow_id_used=workflow_id)
        return {
            "workflow": wf,
            "instance_id": instance_id
        }
    except Exception as e:
        _log("error", instance_id_used=instance_id, workflow_id_used=workflow_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def update_workflow(instance_id, workflow_id, name=None, definition=None, settings=None, project_id=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance_id_used=None, meta=None):
        logs = _load("n8n_assets_and_audit.json")
        req_id = "n8n_ast_" + secrets.token_hex(12).upper()
        row = {
            "id": req_id,
            "instance_id": instance_id_used or instance_id or "n8n_ins_UNKNOWN",
            "asset_type": "audit_report",
            "external_id": None,
            "workflow_id": workflow_id if isinstance(workflow_id, str) else None,
            "project_id": project_id if isinstance(project_id, str) else None,
            "owner_principal_id": None,
            "name": "request_log:update-workflow",
            "key": None,
            "value_encrypted": None,
            "credential_type": None,
            "data_encrypted": None,
            "schema": None,
            "execution_status": None,
            "started_at": None,
            "stopped_at": None,
            "execution_data": None,
            "tag_id": None,
            "report": {
                "endpoint": "update-workflow",
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "meta": meta or {}
            },
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("n8n_assets_and_audit.json", logs)

    # Validate required IDs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", meta={"error_code": "VALIDATION_ERROR", "field": "instance_id"})
        return _err("VALIDATION_ERROR", "Malformed instance_id.", field="instance_id")
    if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
        _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "field": "workflow_id"})
        return _err("VALIDATION_ERROR", "Malformed workflow_id.", field="workflow_id")

    # Validate optional fields
    if name is not None and not isinstance(name, str):
        _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "field": "name"})
        return _err("VALIDATION_ERROR", "Field 'name' must be a string.", field="name")
    if definition is not None and not isinstance(definition, dict):
        _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "field": "definition"})
        return _err("VALIDATION_ERROR", "Field 'definition' must be an object.", field="definition")
    if settings is not None and not isinstance(settings, dict):
        _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "field": "settings"})
        return _err("VALIDATION_ERROR", "Field 'settings' must be an object.", field="settings")
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^n8n_prj_[0-9A-Z]{18,}$", project_id):
            _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "field": "project_id"})
            return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")

    # Enforce: definition shape must include nodes[] and connections{} when provided (business rule)
    if isinstance(definition, dict):
        if "nodes" not in definition or "connections" not in definition:
            _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "rule": "definition keys"})
            return _err("VALIDATION_ERROR", "definition must contain keys 'nodes' (array) and 'connections' (object).", field="definition")
        if not isinstance(definition.get("nodes"), list):
            _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "field": "definition.nodes"})
            return _err("VALIDATION_ERROR", "definition.nodes must be an array.", field="definition.nodes")
        if not isinstance(definition.get("connections"), dict):
            _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "field": "definition.connections"})
            return _err("VALIDATION_ERROR", "definition.connections must be an object.", field="definition.connections")

    # Load and authorize (ambient auth): instance must be active
    instances = _load("n8n_instances.json")
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id_used=instance_id, meta={"error_code": "NOT_FOUND", "resource": "instance"})
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
    if inst.get("status") != "active":
        _log("error", instance_id_used=instance_id, meta={"error_code": "UNAUTHORIZED", "reason": "instance_not_active"})
        return _err("UNAUTHORIZED", "Instance is not active.", instance_id=instance_id)

    workflows = _load("n8n_workflows.json")
    wf_idx = None
    wf = None
    for i, r in enumerate(workflows):
        if r.get("id") == workflow_id and r.get("instance_id") == instance_id:
            wf_idx = i
            wf = r
            break
    if not wf or wf.get("status") == "deleted":
        _log("error", instance_id_used=instance_id, meta={"error_code": "NOT_FOUND", "resource": "workflow"})
        return _err("NOT_FOUND", "Workflow not found.", workflow_id=workflow_id)

    # If project_id provided, validate project existence and not deleted
    if project_id is not None:
        projects = _load("n8n_projects.json")
        prj = next((p for p in projects if p.get("id") == project_id and p.get("instance_id") == instance_id and p.get("status") != "deleted"), None)
        if not prj:
            _log("error", instance_id_used=instance_id, meta={"error_code": "NOT_FOUND", "resource": "project"})
            return _err("NOT_FOUND", "Target project not found.", project_id=project_id)

    # Enforce: cannot directly toggle active via this tool
    if isinstance(definition, dict) and ("active" in definition or "status" in definition):
        # definition may legitimately contain arbitrary n8n fields, but we disallow attempts to smuggle activation/lifecycle
        _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "rule": "no direct toggle"})
        return _err("VALIDATION_ERROR", "Activation/lifecycle cannot be changed via update-workflow; use activate-workflow/deactivate-workflow.", field="definition")

    # Enforce unique(instance_id, name) where status != 'deleted' if name is changing
    if name is not None:
        for r in workflows:
            if r.get("instance_id") == instance_id and r.get("status") != "deleted" and r.get("name") == name and r.get("id") != workflow_id:
                _log("error", instance_id_used=instance_id, meta={"error_code": "CONFLICT", "constraint": "unique(instance_id,name)"})
                return _err("CONFLICT", "A workflow with this name already exists in the instance.", field="name")

    # Determine updater principal (ambient): pick an active principal on instance if available
    principals = _load("n8n_principals.json")
    principal = next((p for p in principals if p.get("instance_id") == instance_id and p.get("status") == "active"), None)
    updater_id = principal.get("id") if principal else None

    # Apply updates
    changed = False
    new_wf = dict(wf)

    if name is not None and name != wf.get("name"):
        new_wf["name"] = name
        changed = True
    if definition is not None:
        new_wf["definition"] = definition
        changed = True
    if settings is not None:
        new_wf["settings"] = settings
        changed = True
    if project_id is not None and project_id != wf.get("project_id"):
        new_wf["project_id"] = project_id
        changed = True

    if not changed:
        # No effect must not be reported as success
        _log("error", instance_id_used=instance_id, meta={"error_code": "VALIDATION_ERROR", "reason": "no_changes"})
        return _err("VALIDATION_ERROR", "No updatable fields were provided or values are unchanged.")

    # Preserve activation invariants: active = (status == 'active')
    st = new_wf.get("status")
    if st == "active":
        new_wf["active"] = True
    else:
        new_wf["active"] = False

    new_wf["updated_by_principal_id"] = updater_id
    new_wf["updated_at"] = now

    workflows[wf_idx] = new_wf
    _save("n8n_workflows.json", workflows)

    _log("ok", instance_id_used=instance_id, meta={"workflow_id": workflow_id})
    return {"workflow": new_wf}

def activate_workflow(instance_id, workflow_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "activate-workflow"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"n8n_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "instance_id": instance_id,
            "workflow_id": workflow_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error
        })
        _save("n8n_request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
            e = _err("VALIDATION_ERROR", "workflow_id is invalid", workflow_id=workflow_id)
            _append_log("error", e["error"])
            return e

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if inst.get("status") != "active":
            e = _err("UNAUTHORIZED", "Active instance required.", rule="active_instance_required", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        workflows = _load("n8n_workflows.json")
        if not isinstance(workflows, list):
            workflows = []

        wf = next((w for w in workflows if w.get("id") == workflow_id and w.get("instance_id") == instance_id and w.get("status") != "deleted"), None)
        if not wf:
            # Relax matching: some stores may not set instance_id consistently; still ensure workflow exists and not deleted
            wf = next((w for w in workflows if w.get("id") == workflow_id and w.get("status") != "deleted"), None)
            if wf and wf.get("instance_id") and wf.get("instance_id") != instance_id:
                e = _err("NOT_FOUND", "Workflow not found.", instance_id=instance_id, workflow_id=workflow_id)
                _append_log("error", e["error"])
                return e
        if not wf:
            e = _err("NOT_FOUND", "Workflow not found.", instance_id=instance_id, workflow_id=workflow_id)
            _append_log("error", e["error"])
            return e

        # Validate workflow definition shape required by constraints
        definition = wf.get("definition")
        if not isinstance(definition, dict) or "nodes" not in definition or "connections" not in definition or not isinstance(definition.get("nodes"), list) or not isinstance(definition.get("connections"), dict):
            e = _err("CONFLICT", "Workflow cannot be activated due to invalid configuration.", rule="invalid_workflow_definition", workflow_id=workflow_id)
            _append_log("error", e["error"])
            return e

        # Lifecycle transitions for n8n_workflows.status
        transitions = {
            "draft": ["inactive", "active", "deleted"],
            "inactive": ["active", "deleted"],
            "active": ["inactive", "deleted"],
            "deleted": []
        }
        cur = wf.get("status")
        if cur not in transitions:
            e = _err("INVALID_TRANSITION", "Workflow has invalid current status.", workflow_id=workflow_id, status=cur)
            _append_log("error", e["error"])
            return e
        if "active" not in transitions[cur]:
            # already active is idempotent
            if cur == "active":
                wf["active"] = True
                _append_log("ok", None)
                return {"workflow_id": wf.get("id"), "instance_id": instance_id, "status": wf.get("status"), "active": True, "updated_at": wf.get("updated_at")}
            e = _err("INVALID_TRANSITION", "Cannot activate workflow from current state.", workflow_id=workflow_id, from_status=cur, to_status="active")
            _append_log("error", e["error"])
            return e

        wf["status"] = "active"
        wf["active"] = True
        wf["updated_at"] = _now()
        _save("n8n_workflows.json", workflows)

        _append_log("ok", None)
        return {
            "workflow_id": wf.get("id"),
            "instance_id": instance_id,
            "status": wf.get("status"),
            "active": wf.get("active"),
            "updated_at": wf.get("updated_at")
        }
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected error while activating workflow.", detail=str(ex))
        try:
            _append_log("error", e["error"])
        except Exception:
            pass
        return e

def deactivate_workflow(instance_id, workflow_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "deactivate-workflow"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"n8n_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "instance_id": instance_id,
            "workflow_id": workflow_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error
        })
        _save("n8n_request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
            e = _err("VALIDATION_ERROR", "workflow_id is invalid", workflow_id=workflow_id)
            _append_log("error", e["error"])
            return e

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if inst.get("status") != "active":
            e = _err("UNAUTHORIZED", "Active instance required.", rule="active_instance_required", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        workflows = _load("n8n_workflows.json")
        if not isinstance(workflows, list):
            workflows = []

        wf = next((w for w in workflows if w.get("id") == workflow_id and w.get("instance_id") == instance_id and w.get("status") != "deleted"), None)
        if not wf:
            wf = next((w for w in workflows if w.get("id") == workflow_id and w.get("status") != "deleted"), None)
            if wf and wf.get("instance_id") and wf.get("instance_id") != instance_id:
                e = _err("NOT_FOUND", "Workflow not found.", instance_id=instance_id, workflow_id=workflow_id)
                _append_log("error", e["error"])
                return e
        if not wf:
            e = _err("NOT_FOUND", "Workflow not found.", instance_id=instance_id, workflow_id=workflow_id)
            _append_log("error", e["error"])
            return e

        transitions = {
            "draft": ["inactive", "active", "deleted"],
            "inactive": ["active", "deleted"],
            "active": ["inactive", "deleted"],
            "deleted": []
        }
        cur = wf.get("status")
        if cur not in transitions:
            e = _err("INVALID_TRANSITION", "Workflow has invalid current status.", workflow_id=workflow_id, status=cur)
            _append_log("error", e["error"])
            return e

        # Idempotent if already inactive (or draft treated as inactive toggle not allowed unless via transition graph)
        if cur in ("inactive", "draft"):
            wf["status"] = "inactive" if cur != "draft" else "draft"
            wf["active"] = False
            wf["updated_at"] = _now()
            _save("n8n_workflows.json", workflows)
            _append_log("ok", None)
            return {"workflow_id": wf.get("id"), "instance_id": instance_id, "status": wf.get("status"), "active": False, "updated_at": wf.get("updated_at")}

        if "inactive" not in transitions[cur]:
            e = _err("INVALID_TRANSITION", "Cannot deactivate workflow from current state.", workflow_id=workflow_id, from_status=cur, to_status="inactive")
            _append_log("error", e["error"])
            return e

        wf["status"] = "inactive"
        wf["active"] = False
        wf["updated_at"] = _now()
        _save("n8n_workflows.json", workflows)

        _append_log("ok", None)
        return {
            "workflow_id": wf.get("id"),
            "instance_id": instance_id,
            "status": wf.get("status"),
            "active": wf.get("active"),
            "updated_at": wf.get("updated_at")
        }
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected error while deactivating workflow.", detail=str(ex))
        try:
            _append_log("error", e["error"])
        except Exception:
            pass
        return e

def list_projects(instance_id, status=None, created_by_principal_id=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-projects"

    def _append_log(status_s, credential_used=None, error_code=None):
        fname_candidates = ["n8n_request_logs.json", "request_logs.json", "api_request_logs.json", "usage.json", "n8n_usage.json", "n8n_assets_and_audit.json"]
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)
        for fn in fname_candidates:
            path = os.path.join(_DB, fn)
            if not os.path.exists(path):
                continue
            data = _load(fn)
            if not isinstance(data, list):
                continue
            data.append({
                "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("="),
                "timestamp": now,
                "endpoint": endpoint,
                "instance_id": instance_id,
                "credential_used": credential_used,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
            })
            _save(fn, data)
            break

    # ---- validation ----
    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed instance_id.")

        if status is not None and status not in ("active", "archived", "deleted"):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter.")

        if created_by_principal_id is not None:
            if not isinstance(created_by_principal_id, str) or not re.match(r"^n8n_usr_[0-9A-Z]{18,}$", created_by_principal_id):
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Malformed created_by_principal_id.")

        if search is not None and not isinstance(search, str):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "search must be a string.")

        if sort_by is not None and sort_by not in ("created_at", "updated_at", "name"):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_by.")
        if sort_order is not None and sort_order not in ("asc", "desc"):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order.")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit out of range (1-200).")
        if cursor is not None and not isinstance(cursor, str):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.")
    except Exception:
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid request.")

    # ---- instance gating: must have active instance ----
    instances = _load("n8n_instances.json")
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id and r.get("status") == "active"), None)
    if not inst:
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Active instance not found.")

    # ---- enterprise gating for projects ----
    ef = inst.get("enterprise_features") if isinstance(inst.get("enterprise_features"), dict) else {}
    if not ef.get("projects_enabled", False):
        _append_log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Projects feature not enabled for this instance.")

    projects = _load("n8n_projects.json")
    rows = [p for p in projects if isinstance(p, dict) and p.get("instance_id") == instance_id]

    # filters
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if created_by_principal_id is not None:
        rows = [p for p in rows if p.get("created_by_principal_id") == created_by_principal_id]
    if search:
        q = search.casefold()
        def _hay(p):
            n = p.get("name") or ""
            d = p.get("description") or ""
            return (str(n) + "\n" + str(d)).casefold()
        rows = [p for p in rows if q in _hay(p)]

    # sort
    sort_by_eff = sort_by or "created_at"
    sort_order_eff = sort_order or "desc"
    reverse = (sort_order_eff == "desc")

    def _sort_key(p):
        v = p.get(sort_by_eff)
        if sort_by_eff in ("created_at", "updated_at"):
            # ISO timestamps sort lexicographically if consistent; fall back to empty
            return v or ""
        if sort_by_eff == "name":
            return (p.get("name") or "").casefold()
        return v or ""

    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)

    # cursor paging: cursor is base64url of integer offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            if not raw.startswith("off:"):
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("ascii").rstrip("=")

    # summaries
    summaries = []
    for p in page:
        summaries.append({
            "id": p.get("id"),
            "instance_id": p.get("instance_id"),
            "name": p.get("name"),
            "description": p.get("description"),
            "created_by_principal_id": p.get("created_by_principal_id"),
            "status": p.get("status"),
            "created_at": p.get("created_at"),
            "updated_at": p.get("updated_at"),
        })

    _append_log("ok")

    return {
        "projects": summaries,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }
    }

def create_project(instance_id, name, description=None, created_by_principal_id=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-project"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "n8n_prj_" + "".join(secrets.choice(alphabet) for _ in range(20))

    def _append_log(status, error=None, project_id=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"n8n_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "instance_id": instance_id,
            "project_id": project_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error
        })
        _save("n8n_request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if not isinstance(name, str) or len(name.strip()) < 1:
            e = _err("VALIDATION_ERROR", "name is required", field="name")
            _append_log("error", e["error"])
            return e
        name = name.strip()
        if description is not None and not isinstance(description, str):
            e = _err("VALIDATION_ERROR", "description must be a string", field="description")
            _append_log("error", e["error"])
            return e
        if created_by_principal_id is not None:
            if not isinstance(created_by_principal_id, str) or not re.match(r"^n8n_usr_[0-9A-Z]{18,}$", created_by_principal_id):
                e = _err("VALIDATION_ERROR", "created_by_principal_id is invalid", created_by_principal_id=created_by_principal_id)
                _append_log("error", e["error"])
                return e

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if inst.get("status") != "active":
            e = _err("UNAUTHORIZED", "Active instance required.", rule="active_instance_required", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        ent = inst.get("enterprise_features") if isinstance(inst.get("enterprise_features"), dict) else {}
        # Accept multiple possible key spellings from stored discovery
        projects_enabled = bool(ent.get("projects_enabled") or ent.get("projectsEnabled") or ent.get("projects") or ent.get("projects_enabled_required"))
        if not projects_enabled:
            e = _err("UNAUTHORIZED", "Projects feature not enabled for this instance.", rule="projects_enabled_required", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        principals = _load("n8n_principals.json")
        if not isinstance(principals, list):
            principals = []
        if created_by_principal_id is not None:
            p = next((u for u in principals if u.get("id") == created_by_principal_id and u.get("instance_id") == instance_id and u.get("status") != "deleted"), None)
            if not p:
                e = _err("NOT_FOUND", "created_by_principal_id not found in instance.", instance_id=instance_id, created_by_principal_id=created_by_principal_id)
                _append_log("error", e["error"])
                return e

        projects = _load("n8n_projects.json")
        if not isinstance(projects, list):
            projects = []

        # Unique(instance_id, name) among non-deleted
        if any(prj for prj in projects if prj.get("instance_id") == instance_id and prj.get("name") == name and prj.get("status") != "deleted"):
            e = _err("CONFLICT", "Project name already exists in this instance.", rule="unique_instance_name", instance_id=instance_id, name=name)
            _append_log("error", e["error"])
            return e

        pid = _gen_id()
        now = _now()
        row = {
            "id": pid,
            "instance_id": instance_id,
            "name": name,
            "description": description,
            "created_by_principal_id": created_by_principal_id,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        projects.append(row)
        _save("n8n_projects.json", projects)

        _append_log("ok", None, project_id=pid)
        return {"project": row}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected error while creating project.", detail=str(ex))
        try:
            _append_log("error", e["error"])
        except Exception:
            pass
        return e

