    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
