            return e
        if "deleted" not in transitions[cur]:
            e = _err("INVALID_TRANSITION", "Cannot delete project from current state.", project_id=project_id, from_status=cur, to_status="deleted")
            _append_log("error", e["error"])
            return e

        prj["status"] = "deleted"
        prj["updated_at"] = _now()
        _save("n8n_projects.json", projects)

        _append_log("ok", None)
        return {"project_id": project_id, "deleted": True, "status": "deleted", "updated_at": prj.get("updated_at")}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected error while deleting project.", detail=str(ex))
        try:
            _append_log("error", e["error"])
        except Exception:
            pass
        return e

def update_project(instance_id, project_id, name, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update-project"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, extra=None):
        try:
            logs = _load("n8n_request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"n8n_req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "instance_id": instance_id if isinstance(instance_id, str) else None,
                "credential_id": None,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now(),
                "extra": extra or {}
            })
            _save("n8n_request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error")
        return _err("VALIDATION_ERROR", "instance_id is malformed")
    if not isinstance(project_id, str) or not re.match(r"^n8n_prj_[0-9A-Z]{18,}$", project_id):
        _log("error")
        return _err("VALIDATION_ERROR", "project_id is malformed")
    if not isinstance(name, str) or len(name.strip()) < 1:
        _log("error")
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    name = name.strip()

    instances = _load("n8n_instances.json")
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log("error")
        return _err("NOT_FOUND", "instance not found")
    if inst.get("status") != "active":
        _log("error")
        return _err("UNAUTHORIZED", "instance is not active")
    ent = inst.get("enterprise_features") if isinstance(inst.get("enterprise_features"), dict) else {}
    if not ent.get("projects_enabled", False):
        _log("error")
        return _err("UNAUTHORIZED", "projects are not enabled for this instance")

    projects = _load("n8n_projects.json")
    idx = None
    row = None
    for i, p in enumerate(projects):
        if isinstance(p, dict) and p.get("id") == project_id:
            idx = i
            row = p
            break
    if row is None or row.get("instance_id") != instance_id:
        _log("error")
        return _err("NOT_FOUND", "project not found for this instance")

    # Cannot update deleted
    if row.get("status") == "deleted":
        _log("error")
        return _err("INVALID_TRANSITION", "cannot update a deleted project")

    # Unique(instance_id, name)
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("id") != project_id and p.get("instance_id") == instance_id and p.get("name") == name:
            _log("error")
            return _err("CONFLICT", "project name already exists in this instance")

    # Idempotent update allowed (but must have effect? if same name, still touch updated_at)
    ts = _now()
    row["name"] = name
    row["updated_at"] = ts
    projects[idx] = row
    _save("n8n_projects.json", projects)

    _log("ok", extra={"project_id": project_id})
    return {"data": row}

def list_users(instance_id, status=None, role=None, principal_type=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-users"
    used_credential = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("n8n_assets_and_audit.json")
        logs.append({
            "id": "n8n_aud_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("="),
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "asset_type": "audit_report",
            "external_id": None,
            "workflow_id": None,
            "project_id": None,
            "owner_principal_id": None,
            "name": endpoint,
            "key": None,
            "value_encrypted": None,
            "credential_type": None,
            "data_encrypted": None,
            "schema": None,
            "execution_status": None,
            "started_at": _now(),
            "stopped_at": _now(),
            "execution_data": {"endpoint": endpoint, "status": status_s, "error_code": error_code, "latency_ms": latency_ms, "credential": used_credential},
            "tag_id": None,
            "report": {"event": "request_log", "endpoint": endpoint, "status": status_s, "error_code": error_code, "latency_ms": latency_ms, "credential": used_credential},
            "status": "active",
            "created_at": _now(),
            "updated_at": _now()
        })
        _save("n8n_assets_and_audit.json", logs)

    def _check_rate_limit():
        # Simple per-instance rolling limit: 300 requests/min across all endpoints.
        if not isinstance(instance_id, str):
            return None
        logs = _load("n8n_assets_and_audit.json")
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("asset_type") != "audit_report":
                continue
            if r.get("report", {}).get("event") != "request_log":
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 300:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit=300, window_seconds=60)
        return None

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or len(c) > 2000:
            return "bad", None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"=" * (-len(c) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "bad", None
            off = obj.get("offset")
            sig = obj.get("sig")
            if not isinstance(off, int) or off < 0:
                return "bad", None
            if not isinstance(sig, str):
                return "bad", None
            # lightweight integrity check against tampering
            payload = json.dumps({"offset": off}, separators=(",", ":"), sort_keys=True).encode("utf-8")
            exp = hashlib.sha256(payload).hexdigest()
            if sig != exp:
                return "bad", None
            return None, off
        except Exception:
            return "bad", None

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        e = _err("VALIDATION_ERROR", "Invalid instance_id.")
        _log("error", e["error"]["code"])
        return e

    allowed_status = {"invited", "active", "suspended", "deleted"}
    allowed_role = {"owner", "admin", "member", "viewer"}
    allowed_type = {"user", "service"}
    allowed_sort_by = {"created_at", "updated_at", "email", "last_login_at"}
    allowed_sort_order = {"asc", "desc"}

    if status is not None and status not in allowed_status:
        e = _err("VALIDATION_ERROR", "Invalid status filter.", allowed=list(sorted(allowed_status)))
        _log("error", e["error"]["code"])
        return e
    if role is not None and role not in allowed_role:
        e = _err("VALIDATION_ERROR", "Invalid role filter.", allowed=list(sorted(allowed_role)))
        _log("error", e["error"]["code"])
        return e
    if principal_type is not None and principal_type not in allowed_type:
        e = _err("VALIDATION_ERROR", "Invalid principal_type filter.", allowed=list(sorted(allowed_type)))
        _log("error", e["error"]["code"])
        return e
    if search is not None and not isinstance(search, str):
        e = _err("VALIDATION_ERROR", "Invalid search; must be a string.")
        _log("error", e["error"]["code"])
        return e
    if sort_by is not None and sort_by not in allowed_sort_by:
        e = _err("VALIDATION_ERROR", "Invalid sort_by.", allowed=list(sorted(allowed_sort_by)))
        _log("error", e["error"]["code"])
        return e
    if sort_order is not None and sort_order not in allowed_sort_order:
        e = _err("VALIDATION_ERROR", "Invalid sort_order.", allowed=list(sorted(allowed_sort_order)))
        _log("error", e["error"]["code"])
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 200.")
        _log("error", e["error"]["code"])
        return e

    cur_err, offset = _parse_cursor(cursor)
    if cur_err:
        e = _err("VALIDATION_ERROR", "Invalid cursor.")
        _log("error", e["error"]["code"])
        return e
    if offset is None:
        offset = 0

    rl = _check_rate_limit()
    if rl:
        _log("error", rl["error"]["code"])
        return rl

    instances = _load("n8n_instances.json")
    inst = next((i for i in instances if i.get("id") == instance_id), None)
    if not inst:
        e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
        _log("error", e["error"]["code"])
        return e
    if inst.get("status") != "active":
        e = _err("UNAUTHORIZED", "Instance is not active.")
        _log("error", e["error"]["code"])
        return e

    # Authorization: only permitted for a caller principal with role='owner' on that instance.
    # No explicit credential parameter exists; choose any active owner principal as the "caller context".
    principals = _load("n8n_principals.json")
    caller = next((p for p in principals if p.get("instance_id") == instance_id and p.get("status") == "active" and p.get("role") == "owner"), None)
    if not caller:
        e = _err("UNAUTHORIZED", "Owner role required to list users for this instance.")
        _log("error", e["error"]["code"])
        return e

    rows = [p for p in principals if p.get("instance_id") == instance_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if role is not None:
        rows = [r for r in rows if r.get("role") == role]
    if principal_type is not None:
        rows = [r for r in rows if r.get("principal_type") == principal_type]
    if search is not None and search.strip() != "":
        q = search.strip().lower()
        def _s(v):
            return v.lower() if isinstance(v, str) else ""
        rows = [r for r in rows if (q in _s(r.get("email")) or q in _s(r.get("first_name")) or q in _s(r.get("last_name")))]

    sb = sort_by or "created_at"
    so = sort_order or "desc"

    def _sort_key(r):
        v = r.get(sb)
        # normalize for consistent sort
        if sb in ("created_at", "updated_at", "last_login_at"):
            if not isinstance(v, str):
                return ""
            return v
        if sb == "email":
            return (v or "").lower() if isinstance(v, str) else ""
        return ""

    rows.sort(key=_sort_key, reverse=(so == "desc"))

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":"), sort_keys=True).encode("utf-8")
        sig = hashlib.sha256(payload).hexdigest()
        token = json.dumps({"offset": next_offset, "sig": sig}, separators=(",", ":"), sort_keys=True).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    _log("ok", None)
    return {
        "data": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "offset": offset
        }
    }

def create_users(instance_id, users, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-users"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance=None, detail=None):
        logs = _load("n8n_request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "instance_id": instance,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("n8n_request_logs.json", logs)

    def _gen_id(prefix):
        # n8n_*_[0-9A-Z]{18,}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        raw = uuid.uuid4().hex.upper()
        base36 = ""
        for ch in raw:
            base36 += alphabet[int(ch, 16) % 36]
        return f"{prefix}_{base36}{uuid.uuid4().hex.upper()[:6]}"

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", None, "invalid instance_id")
        return _err("VALIDATION_ERROR", "Malformed instance_id.")
    if not isinstance(users, list) or len(users) < 1:
        _log("error", instance_id, "users must be non-empty array")
        return _err("VALIDATION_ERROR", "Payload malformed: users must be a non-empty array.")
    allowed_roles = {"owner", "admin", "member", "viewer"}
    allowed_status = {"invited", "active", "suspended", "deleted"}

    for i, u in enumerate(users):
        if not isinstance(u, dict):
            _log("error", instance_id, f"user[{i}] not object")
            return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}] must be an object.")
        extra_keys = set(u.keys()) - {"email", "first_name", "last_name", "role", "status"}
        if extra_keys:
            _log("error", instance_id, f"user[{i}] additional properties")
            return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}] contains unsupported fields: {sorted(extra_keys)}.")
        if "email" not in u or "role" not in u:
            _log("error", instance_id, f"user[{i}] missing required")
            return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}] missing required fields (email, role).")
        if not isinstance(u["email"], str) or not u["email"].strip():
            _log("error", instance_id, f"user[{i}] invalid email")
            return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}].email must be a non-empty string.")
        if not isinstance(u["role"], str) or u["role"] not in allowed_roles:
            _log("error", instance_id, f"user[{i}] invalid role")
            return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}].role must be one of {sorted(allowed_roles)}.")
        if "first_name" in u and u["first_name"] is not None and not isinstance(u["first_name"], str):
            _log("error", instance_id, f"user[{i}] invalid first_name")
            return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}].first_name must be a string or null.")
        if "last_name" in u and u["last_name"] is not None and not isinstance(u["last_name"], str):
            _log("error", instance_id, f"user[{i}] invalid last_name")
            return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}].last_name must be a string or null.")
        if "status" in u and u["status"] is not None:
            if not isinstance(u["status"], str) or u["status"] not in allowed_status:
                _log("error", instance_id, f"user[{i}] invalid status")
                return _err("VALIDATION_ERROR", f"Payload malformed: users[{i}].status must be one of {sorted(allowed_status)}.")

    instances = _load("n8n_instances.json")
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id, "instance not found")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    # Business rule: all tools except init-n8n require active instance
    if inst.get("status") != "active":
        _log("error", instance_id, "instance not active")
        return _err("UNAUTHORIZED", "Instance is not active for this operation.", instance_id=instance_id)

    # Ambient auth resolution: find a caller principal that can create users in this instance.
    principals = _load("n8n_principals.json")
    caller = next((p for p in principals
                   if p.get("instance_id") == instance_id and p.get("status") == "active" and p.get("role") in ("owner", "admin")), None)
    if not caller:
        _log("error", instance_id, "no authorized principal")
        return _err("UNAUTHORIZED", "Caller not permitted to create users in this instance.", instance_id=instance_id)

    # Enforce uniqueness (instance_id, email) where email not null, among all principals not deleted
    existing_by_email = {}
    for p in principals:
        if p.get("instance_id") != instance_id:
            continue
        if p.get("status") == "deleted":
            continue
        em = p.get("email")
        if isinstance(em, str) and em:
            existing_by_email[em.strip().lower()] = p

    # Also ensure no duplicates within request payload
    seen = set()
    for u in users:
        eml = u["email"].strip().lower()
        if eml in seen:
            _log("error", instance_id, "duplicate emails in request")
            return _err("VALIDATION_ERROR", "Payload malformed: duplicate emails in users array.", email=u["email"])
        seen.add(eml)

    conflicts = []
    for u in users:
        eml = u["email"].strip().lower()
        if eml in existing_by_email:
            conflicts.append(u["email"])
    if conflicts:
        _log("error", instance_id, "email conflict")
        return _err("CONFLICT", "One or more emails already exist in the instance.", emails=conflicts, instance_id=instance_id)

    created = []
    # Instance policy: accept caller-provided status if present; otherwise default to invited
    for u in users:
        status = u.get("status") or "invited"
        # validate lifecycle value already done; now enforce is_owner = (role == 'owner')
        role = u["role"]
        row = {
            "id": _gen_id("n8n_usr"),
            "instance_id": instance_id,
            "principal_type": "user",
            "email": u["email"].strip(),
            "first_name": u.get("first_name"),
            "last_name": u.get("last_name"),
            "role": role,
            "is_owner": True if role == "owner" else False,
            "status": status,
            "last_login_at": None,
            "created_at": now,
            "updated_at": now,
        }
        principals.append(row)
        created.append(row)

    _save("n8n_principals.json", principals)
    _log("ok", instance_id, {"created": len(created), "caller_principal_id": caller.get("id")})

    return {
        "instance_id": instance_id,
        "users": created,
        "count": len(created),
    }

def get_user(instance_id, user_id=None, email=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-user"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"n8n_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "instance_id": instance_id,
            "user_id": user_id,
            "email": email,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error
        })
        _save("n8n_request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        if user_id is None and (email is None or (isinstance(email, str) and email.strip() == "")):
            e = _err("VALIDATION_ERROR", "Either user_id or email must be provided.", rule="user_lookup_required")
            _append_log("error", e["error"])
            return e
        if user_id is not None and (not isinstance(user_id, str) or not re.match(r"^n8n_usr_[0-9A-Z]{18,}$", user_id)):
            e = _err("VALIDATION_ERROR", "user_id is invalid", user_id=user_id)
            _append_log("error", e["error"])
            return e
        if email is not None and not isinstance(email, str):
            e = _err("VALIDATION_ERROR", "email must be a string", email=email)
            _append_log("error", e["error"])
            return e
        email_norm = email.strip().lower() if isinstance(email, str) else None

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
