        logs.append({
            "id": f"n8n_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "instance_id": instance_id,
            "user_id": user_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error
        })
        _save("n8n_request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if not isinstance(user_id, str) or not re.match(r"^n8n_usr_[0-9A-Z]{18,}$", user_id):
            e = _err("VALIDATION_ERROR", "user_id is invalid", user_id=user_id)
            _append_log("error", e["error"])
            return e

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if inst.get("status") != "active":
            e = _err("UNAUTHORIZED", "Active instance required.", rule="active_instance_required", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        principals = _load("n8n_principals.json")
        if not isinstance(principals, list):
            principals = []
        target = next((p for p in principals if p.get("id") == user_id and p.get("instance_id") == instance_id and p.get("status") != "deleted"), None)
        if not target:
            e = _err("NOT_FOUND", "User not found.", instance_id=instance_id, user_id=user_id)
            _append_log("error", e["error"])
            return e

        # Must not allow deleting last remaining owner in the instance.
        owners_active = [p for p in principals if p.get("instance_id") == instance_id and p.get("status") != "deleted" and (p.get("role") == "owner" or p.get("is_owner") is True)]
        is_target_owner = (target.get("role") == "owner" or target.get("is_owner") is True)
        if is_target_owner and len(owners_active) <= 1:
            e = _err("CONFLICT", "Cannot delete the last remaining owner in the instance.", rule="cannot_delete_last_owner", instance_id=instance_id, user_id=user_id)
            _append_log("error", e["error"])
            return e

        transitions = {"invited": ["active", "deleted"], "active": ["suspended", "deleted"], "suspended": ["active", "deleted"], "deleted": []}
        cur = target.get("status")
        if cur not in transitions:
            e = _err("INVALID_TRANSITION", "User has invalid current status.", user_id=user_id, status=cur)
            _append_log("error", e["error"])
            return e
        if "deleted" not in transitions[cur]:
            e = _err("INVALID_TRANSITION", "Cannot delete user from current state.", user_id=user_id, from_status=cur, to_status="deleted")
            _append_log("error", e["error"])
            return e

        target["status"] = "deleted"
        target["updated_at"] = _now()
        _save("n8n_principals.json", principals)

        _append_log("ok", None)
        return {"user_id": user_id, "deleted": True, "status": "deleted", "updated_at": target.get("updated_at")}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected error while deleting user.", detail=str(ex))
        try:
            _append_log("error", e["error"])
        except Exception:
            pass
        return e

def list_variables(instance_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_used=None, error_code=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "list-variables",
            "instance_id": instance_id,
            "credential_used": credential_used,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        })
        _save("n8n_request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            v = json.loads(raw.decode("utf-8"))
            return v if isinstance(v, dict) else None
        except Exception:
            return None

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instance_id is malformed")

        if status is not None and status not in ("active", "disabled", "deleted"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

        if sort is None:
            sort = "created_at"
        if sort not in ("created_at", "updated_at", "name", "key"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort field")

        if order is None:
            order = "asc"
        if order not in ("asc", "desc"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort order")

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
        if inst.get("status") != "active":
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Instance is not active", instance_id=instance_id)

        ef = inst.get("enterprise_features") if isinstance(inst.get("enterprise_features"), dict) else {}
        if not ef.get("variables_enabled", False):
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Variables are not enabled for this instance", instance_id=instance_id)

        # Ambient auth: require there exists an active principal in this instance.
        principals = _load("n8n_principals.json")
        if not isinstance(principals, list):
            principals = []
        caller = next((p for p in principals if p.get("instance_id") == instance_id and p.get("status") == "active"), None)
        if not caller:
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active principal available for this instance")

        assets = _load("n8n_assets_and_audit.json")
        if not isinstance(assets, list):
            assets = []

        rows = [
            a for a in assets
            if a.get("instance_id") == instance_id
            and a.get("asset_type") == "variable"
        ]
        if status is not None:
            rows = [a for a in rows if a.get("status") == status]
        else:
            # Default: exclude deleted
            rows = [a for a in rows if a.get("status") != "deleted"]

        # Sort
        reverse = (order == "desc")
        def _k(a):
            v = a.get(sort)
            # keep stable sorting for None
            if v is None:
                return ""
            return v if isinstance(v, str) else str(v)
        rows.sort(key=lambda a: (_k(a), a.get("id", "")), reverse=reverse)

        # Cursor handling
        start = 0
        cur_obj = _decode_cursor(cursor) if cursor is not None else None
        if cursor is not None:
            if cur_obj is None or cur_obj.get("v") != 1 or cur_obj.get("instance_id") != instance_id:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            if cur_obj.get("sort") != sort or cur_obj.get("order") != order or cur_obj.get("status") != (status if status is not None else "__default__"):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Cursor does not match requested query parameters")
            try:
                start = int(cur_obj.get("offset", 0))
            except Exception:
                start = 0
            if start < 0:
                start = 0

        total = len(rows)
        page = rows[start:start + limit]
        next_offset = start + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            next_cursor = _encode_cursor({
                "v": 1,
                "instance_id": instance_id,
                "status": status if status is not None else "__default__",
                "sort": sort,
                "order": order,
                "offset": next_offset,
            })

        _log("ok")
        return {
            "data": {
                "variables": page,
                "pagination": {
                    "total": total,
                    "limit": limit,
                    "cursor": cursor,
                    "next_cursor": next_cursor,
                    "has_more": has_more,
                },
                "sort": {"field": sort, "order": order},
                "filters": {"status": status},
            }
        }
    except Exception as e:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def create_variable(instance_id, key, value, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _gen_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
    def _log(status_code, error_code=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("="),
            "endpoint": "create-variable",
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "status": status_code,
            "error_code": error_code,
            "instance_id": instance_id
        })
        _save("n8n_request_logs.json", logs)

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id is malformed")
    if not isinstance(key, str) or len(key) < 1:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "key must be a non-empty string")
    if not isinstance(value, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "value must be a string")

    instances = _load("n8n_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
    if inst.get("status") != "active":
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Instance is not active")
    ef = inst.get("enterprise_features") if isinstance(inst.get("enterprise_features"), dict) else {}
    if not ef.get("variables_enabled", False):
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Variables management requires enterprise variables feature")

    assets = _load("n8n_assets_and_audit.json")
    if not isinstance(assets, list):
        assets = []

    # Uniqueness on (instance_id, asset_type='variable', key) where status != 'deleted'
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("instance_id") == instance_id and a.get("asset_type") == "variable" and a.get("status") != "deleted" and a.get("key") == key:
            _log(409, "CONFLICT")
            return _err("CONFLICT", "A variable with this key already exists", key=key)

    # Store encrypted value (envelope placeholder; deterministic for offline use)
    # Note: This is not real crypto; it's a reversible encoding with integrity tag for datastore behavior.
    salt = os.urandom(8)
    blob = {
        "v": value,
        "s": base64.b64encode(salt).decode("utf-8")
    }
    pt = json.dumps(blob, separators=(",", ":")).encode("utf-8")
    tag = hashlib.sha256(b"n8n_var|" + salt + pt).hexdigest()
    value_encrypted = "enc_v1:" + base64.b64encode(pt).decode("utf-8") + ":" + tag

    now = _now()
    row = {
        "id": _gen_id("n8n_ast_"),
        "instance_id": instance_id,
        "asset_type": "variable",
        "external_id": None,
        "workflow_id": None,
        "project_id": None,
        "owner_principal_id": None,
        "name": None,
        "key": key,
        "value_encrypted": value_encrypted,
        "credential_type": None,
        "data_encrypted": None,
        "schema": None,
        "execution_status": None,
        "started_at": None,
        "stopped_at": None,
        "execution_data": None,
        "tag_id": None,
        "report": None,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    assets.append(row)
    _save("n8n_assets_and_audit.json", assets)

    _log(201)
    return {"data": row}

