    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id is malformed")
    if not isinstance(name, str) or len(name) < 1:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if not isinstance(type, str) or len(type) < 1:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type must be a non-empty string")
    if not isinstance(data, dict):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "data must be an object")
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^n8n_prj_[0-9A-Z]{18,}$", project_id):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id is malformed")

    # Resolve instance + enforce active
    instances = _load("n8n_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
    if inst.get("status") != "active":
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Instance is not active")

    # Validate project if provided
    if project_id is not None:
        projects = _load("n8n_projects.json")
        if not isinstance(projects, list):
            projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id and p.get("instance_id") == instance_id and p.get("status") != "deleted"), None)
        if not prj:
            _log(404, "NOT_FOUND")
            return _err("NOT_FOUND", "Project not found in instance", project_id=project_id)

    # Resolve caller principal ambiently: choose an active owner/admin/member principal if available
    principals = _load("n8n_principals.json")
    if not isinstance(principals, list):
        principals = []
    owner = None
    for r in principals:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("status") != "active":
            continue
        if r.get("role") in ("owner", "admin", "member"):
            owner = r
            break
    if owner is None:
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active principal available to own credential in this instance")

    assets = _load("n8n_assets_and_audit.json")
    if not isinstance(assets, list):
        assets = []

    # Optional: validate against credential schema if present
    schema_row = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("instance_id") == instance_id and a.get("asset_type") == "credential_schema" and a.get("credential_type") == type and a.get("status") != "deleted":
            schema_row = a
            break
    if schema_row and isinstance(schema_row.get("schema"), dict):
        sch = schema_row["schema"]
        # Minimal conformance check: required fields list if present
        required = sch.get("required")
        if isinstance(required, list):
            missing = [k for k in required if k not in data]
            if missing:
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Credential data missing required fields", missing=missing, credential_type=type)

    # Store encrypted data (envelope placeholder)
    salt = os.urandom(8)
    blob = {"t": type, "d": data, "s": base64.b64encode(salt).decode("utf-8")}
    pt = json.dumps(blob, separators=(",", ":"), sort_keys=True).encode("utf-8")
    tag = hashlib.sha256(b"n8n_cred|" + salt + pt).hexdigest()
    data_encrypted = "enc_v1:" + base64.b64encode(pt).decode("utf-8") + ":" + tag

    now = _now()
    row = {
        "id": _gen_id("n8n_ast_"),
        "instance_id": instance_id,
        "asset_type": "credential",
        "external_id": None,
        "workflow_id": None,
        "project_id": project_id,
        "owner_principal_id": owner.get("id"),
        "name": name,
        "key": None,
        "value_encrypted": None,
        "credential_type": type,
        "data_encrypted": data_encrypted,
        "schema": None,
        "execution_status": None,
        "started_at": None,
        "stopped_at": None,
        "execution_data": None,
        "tag_id": None,
        "report": None,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    assets.append(row)
    _save("n8n_assets_and_audit.json", assets)

    _log(201)
    return {"data": row}

def delete_credential(instance_id, credential_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-credential"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"n8n_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "instance_id": instance_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error
        })
        _save("n8n_request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if not isinstance(credential_id, str) or not re.match(r"^[0-9]+$|^n8n_ast_[0-9A-Z]{18,}$", credential_id):
            e = _err("VALIDATION_ERROR", "credential_id is invalid", credential_id=credential_id)
            _append_log("error", e["error"])
            return e

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if inst.get("status") != "active":
            e = _err("UNAUTHORIZED", "Active instance required.", rule="active_instance_required", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        assets = _load("n8n_assets_and_audit.json")
        if not isinstance(assets, list):
            assets = []
        cred = next((a for a in assets if a.get("instance_id") == instance_id and a.get("asset_type") == "credential" and a.get("status") != "deleted" and (a.get("id") == credential_id or a.get("external_id") == credential_id)), None)
        if not cred:
            e = _err("NOT_FOUND", "Credential not found.", instance_id=instance_id, credential_id=credential_id)
            _append_log("error", e["error"])
            return e

        # Permission check cannot be enforced without caller principal context; do not incorrectly forbid.
        # If owner_principal_id exists, allow delete (ambient auth assumed satisfied).
        transitions = {"active": ["disabled", "deleted"], "disabled": ["active", "deleted"], "deleted": []}
        cur = cred.get("status")
        if cur not in transitions:
            e = _err("INVALID_TRANSITION", "Credential has invalid current status.", credential_id=credential_id, status=cur)
            _append_log("error", e["error"])
            return e
        if "deleted" not in transitions[cur]:
            e = _err("INVALID_TRANSITION", "Cannot delete credential from current state.", credential_id=credential_id, from_status=cur, to_status="deleted")
            _append_log("error", e["error"])
            return e

        cred["status"] = "deleted"
        cred["updated_at"] = _now()
        _save("n8n_assets_and_audit.json", assets)

        _append_log("ok", None)
        # Return reference/metadata (no secrets)
        return {
            "credential": {
                "id": cred.get("id"),
                "external_id": cred.get("external_id"),
                "instance_id": cred.get("instance_id"),
                "name": cred.get("name"),
                "credential_type": cred.get("credential_type"),
                "owner_principal_id": cred.get("owner_principal_id"),
                "status": cred.get("status"),
                "updated_at": cred.get("updated_at")
            }
        }
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected error while deleting credential.", detail=str(ex))
        try:
            _append_log("error", e["error"])
        except Exception:
            pass
        return e

def list_executions(instance_id, workflow_id=None, external_workflow_id=None, status=None, started_after=None, started_before=None, include_data=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-executions"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 datetime string")
        try:
            # Accept trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(f"{field} must be an RFC3339 datetime string")

    def _audit(status_code, used_instance_id=None, used_principal_id=None, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows = _load("n8n_assets_and_audit.json")
        row = {
            "id": "n8n_aud_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "instance_id": used_instance_id or (instance_id if isinstance(instance_id, str) else "unknown"),
            "asset_type": "audit_report",
            "external_id": None,
            "workflow_id": None,
            "project_id": None,
            "owner_principal_id": used_principal_id,
            "name": f"request:{endpoint}",
            "key": None,
            "value_encrypted": None,
            "credential_type": None,
            "data_encrypted": None,
            "schema": None,
            "execution_status": None,
            "started_at": None,
            "stopped_at": None,
            "execution_data": None,
            "tag_id": None,
            "report": {
                "kind": "request_log",
                "endpoint": endpoint,
                "status": status_code,
                "latency_ms": latency_ms,
                "detail": detail,
                "at": _now_iso(),
            },
            "status": "active",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        rows.append(row)
        _save("n8n_assets_and_audit.json", rows)

    # ---- Validate inputs ----
    if not isinstance(instance_id, str):
        _audit("VALIDATION_ERROR", detail="instance_id type invalid")
        return _err("VALIDATION_ERROR", "instance_id must be a string")
    import re
    if not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="instance_id pattern invalid")
        return _err("VALIDATION_ERROR", "instance_id is invalid")

    if workflow_id is not None:
        if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
            _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="workflow_id invalid")
            return _err("VALIDATION_ERROR", "workflow_id is invalid")
    if external_workflow_id is not None and not isinstance(external_workflow_id, str):
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="external_workflow_id type invalid")
        return _err("VALIDATION_ERROR", "external_workflow_id must be a string")

    allowed_status = {"new", "running", "success", "error", "canceled", "crashed", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="status invalid")
            return _err("VALIDATION_ERROR", "status is invalid", allowed=sorted(list(allowed_status)))

    if include_data is not None and not isinstance(include_data, bool):
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="include_data type invalid")
        return _err("VALIDATION_ERROR", "include_data must be a boolean")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="limit type invalid")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="limit out of range")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    allowed_sort = {"started_at", "stopped_at", "created_at", "updated_at"}
    if sort is None:
        sort = "started_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="sort invalid")
        return _err("VALIDATION_ERROR", "sort is invalid", allowed=sorted(list(allowed_sort)))

    allowed_order = {"asc", "desc"}
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="order invalid")
        return _err("VALIDATION_ERROR", "order is invalid", allowed=sorted(list(allowed_order)))

    if cursor is not None and not isinstance(cursor, str):
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="cursor type invalid")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    try:
        dt_after = _parse_dt(started_after, "started_after")
        dt_before = _parse_dt(started_before, "started_before")
    except ValueError as e:
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail=str(e))
        return _err("VALIDATION_ERROR", str(e))
    if dt_after and dt_before and dt_after > dt_before:
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="started_after > started_before")
        return _err("VALIDATION_ERROR", "started_after must be <= started_before")

    # ---- Auth/instance scope resolution (ambient) ----
    instances = _load("n8n_instances.json")
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if inst is None:
        _audit("NOT_FOUND", used_instance_id=instance_id, detail="instance not found")
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("status") != "active":
        _audit("UNAUTHORIZED", used_instance_id=instance_id, detail="instance not active")
        return _err("UNAUTHORIZED", "Instance is not active")

    # ---- Optional external_workflow_id mapping ----
    workflows = _load("n8n_workflows.json")
    wf_ids = None
    if external_workflow_id is not None:
        # Interpret external_workflow_id as n8n workflow id mirrored in n8n_workflows.id (string).
        # If it matches a stored workflow in this instance, filter to it; if none, return empty set (not an error).
        wf_ids = {w.get("id") for w in workflows if w.get("instance_id") == instance_id and w.get("status") != "deleted" and str(w.get("id")) == str(external_workflow_id)}
        if not wf_ids:
            _audit("OK", used_instance_id=instance_id, detail="no workflows matched external_workflow_id")
            return {
                "executions": [],
                "pagination": {"limit": limit, "total": 0, "has_more": False, "next_cursor": None},
                "instance_id": instance_id,
            }

    # ---- Cursor decoding ----
    def _decode_cursor(c):
        if c is None:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1:
                return None
            if obj.get("instance_id") != instance_id:
                return None
            return obj
        except Exception:
            return None

    cur_obj = _decode_cursor(cursor)
    if cursor is not None and cur_obj is None:
        _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="invalid cursor")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    # ---- Load and filter executions ----
    assets = _load("n8n_assets_and_audit.json")
    execs = []
    for a in assets:
        if a.get("asset_type") != "execution":
            continue
        if a.get("instance_id") != instance_id:
            continue
        if a.get("status") == "deleted":
            continue
        if workflow_id is not None and a.get("workflow_id") != workflow_id:
            continue
        if wf_ids is not None and a.get("workflow_id") not in wf_ids:
            continue
        if status is not None and a.get("execution_status") != status:
            continue

        # started_at range
        sa = a.get("started_at")
        if dt_after or dt_before:
            if not isinstance(sa, str):
                continue
            try:
                sa_dt = _parse_dt(sa, "started_at")
            except ValueError:
                continue
            if dt_after and sa_dt < dt_after:
                continue
            if dt_before and sa_dt > dt_before:
                continue

        execs.append(a)

    # ---- Sort ----
    def _sort_key(row):
        v = row.get(sort)
        if isinstance(v, str):
            try:
                return _parse_dt(v, sort)
            except ValueError:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    reverse = (order == "desc")
    execs.sort(key=_sort_key, reverse=reverse)

    # ---- Apply cursor pagination ----
    def _cursor_tuple(row):
        # stable tie-breaker: (sort_value_iso, id)
        v = row.get(sort)
        if isinstance(v, str):
            sv = v
        else:
            sv = ""
        return (sv, row.get("id") or "")

    if cur_obj is not None:
        after = cur_obj.get("after")
        after_id = cur_obj.get("after_id")
        if not isinstance(after, str) or not isinstance(after_id, str):
            _audit("VALIDATION_ERROR", used_instance_id=instance_id, detail="cursor payload invalid")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        def _is_after(row):
            sv, rid = _cursor_tuple(row)
            if reverse:
                # descending: items "after" are those strictly less than cursor tuple
                return (sv, rid) < (after, after_id)
            else:
                return (sv, rid) > (after, after_id)
        execs = [r for r in execs if _is_after(r)]

    total = len(execs)
    page = execs[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        after, after_id = _cursor_tuple(last)
        payload = {"v": 1, "instance_id": instance_id, "after": after, "after_id": after_id, "sort": sort, "order": order}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    # ---- Shape response; hide execution_data unless requested ----
    out = []
    for r in page:
        rr = dict(r)
        if not include_data:
            rr["execution_data"] = None
        out.append(rr)

    _audit("OK", used_instance_id=instance_id, detail={"returned": len(out), "total": total, "has_more": has_more})

    return {
        "executions": out,
        "pagination": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor},
        "instance_id": instance_id,
    }

def get_execution(instance_id, execution_id, include_data=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
