            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if not isinstance(execution_id, str) or not re.match(r"^[0-9]+$|^n8n_ast_[0-9A-Z]{18,}$", execution_id):
