def create_tag(instance_id, body, **_extra):
    import json, os, datetime, time, re, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_instance_id=None, details=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "create-tag",
            "instance_id": used_instance_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "ts": _now(),
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("n8n_request_logs.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _gen_external_id():
        # n8n tag IDs are typically numeric, but schema allows string; keep opaque string id.
        return "tag_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(16))

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", None, {"code": "VALIDATION_ERROR", "field": "instance_id"})
        return _err("VALIDATION_ERROR", "instance_id is invalid", field="instance_id")
    if not isinstance(body, dict):
        _log("error", instance_id, {"code": "VALIDATION_ERROR", "field": "body"})
        return _err("VALIDATION_ERROR", "body must be an object", field="body")
    name = body.get("name")
    if not isinstance(name, str) or not name.strip():
        _log("error", instance_id, {"code": "VALIDATION_ERROR", "field": "body.name"})
        return _err("VALIDATION_ERROR", "name is required", field="name")
    name = name.strip()

    # Enforce active instance
    instances = _load("n8n_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id, {"code": "NOT_FOUND", "entity": "instance"})
        return _err("NOT_FOUND", "Instance not found", entity="n8n_instance", id=instance_id)
    if inst.get("status") != "active":
        _log("error", instance_id, {"code": "NOT_FOUND", "entity": "instance_active"})
        return _err("NOT_FOUND", "Active instance not found", entity="n8n_instance", id=instance_id, required_status="active")

    assets = _load("n8n_assets_and_audit.json")
    if not isinstance(assets, list):
        assets = []

    # Uniqueness: unique(instance_id, asset_type, name) where asset_type='tag' and status != 'deleted'
    for r in assets:
        if r.get("instance_id") == instance_id and r.get("asset_type") == "tag" and r.get("status") != "deleted":
            if isinstance(r.get("name"), str) and r.get("name").strip().lower() == name.lower():
                _log("error", instance_id, {"code": "CONFLICT", "entity": "tag", "name": name})
                return _err("CONFLICT", "A tag with this name already exists", entity="tag", name=name)

    now = _now()
    new_row = {
        "id": _gen_id("n8n_ast_"),
        "instance_id": instance_id,
        "asset_type": "tag",
        "external_id": _gen_external_id(),
        "workflow_id": None,
        "project_id": None,
        "owner_principal_id": None,
        "name": name,
        "key": None,
        "value_encrypted": None,
        "credential_type": None,
        "data_encrypted": None,
        "schema": None,
        "execution_status": None,
        "started_at": None,
        "stopped_at": None,
        "execution_data": None,
        "tag_id": None,
        "report": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    assets.append(new_row)
    _save("n8n_assets_and_audit.json", assets)

    resp = {
        "id": new_row["id"],
        "instance_id": instance_id,
        "tag_id": new_row["external_id"],
        "name": new_row["name"],
        "status": new_row["status"],
        "created_at": new_row["created_at"],
        "updated_at": new_row["updated_at"],
    }
    _log("ok", instance_id, {"created_tag_asset_id": new_row["id"]})
    return resp

def list_tags(instance_id, limit=None, cursor=None, sort=None, order=None, q=None, **_extra):
    import json, os, datetime, time, re, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_instance_id=None, details=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "list-tags",
            "instance_id": used_instance_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "ts": _now(),
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("n8n_request_logs.json", logs)

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", None, {"code": "VALIDATION_ERROR", "field": "instance_id"})
        return _err("VALIDATION_ERROR", "instance_id is invalid", field="instance_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", instance_id, {"code": "VALIDATION_ERROR", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name"):
        _log("error", instance_id, {"code": "VALIDATION_ERROR", "field": "sort"})
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", instance_id, {"code": "VALIDATION_ERROR", "field": "order"})
        return _err("VALIDATION_ERROR", "order is invalid", field="order")

    offset = _parse_cursor(cursor)
    if offset is None:
        _log("error", instance_id, {"code": "VALIDATION_ERROR", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    if q is not None and (not isinstance(q, str)):
        _log("error", instance_id, {"code": "VALIDATION_ERROR", "field": "q"})
        return _err("VALIDATION_ERROR", "q must be a string", field="q")
    q_norm = (q or "").strip().lower()

    # Enforce active instance
    instances = _load("n8n_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id, {"code": "NOT_FOUND", "entity": "instance"})
        return _err("NOT_FOUND", "Instance not found", entity="n8n_instance", id=instance_id)
    if inst.get("status") != "active":
        _log("error", instance_id, {"code": "NOT_FOUND", "entity": "instance_active"})
        return _err("NOT_FOUND", "Active instance not found", entity="n8n_instance", id=instance_id, required_status="active")

    assets = _load("n8n_assets_and_audit.json")
    if not isinstance(assets, list):
        assets = []

    tags = []
    for r in assets:
        if r.get("instance_id") != instance_id:
            continue
        if r.get("asset_type") != "tag":
            continue
        if r.get("status") == "deleted":
            continue
        nm = r.get("name") or ""
        if q_norm and q_norm not in str(nm).lower():
            continue
        tags.append(r)

    # Sorting
    reverse = (order == "desc")
    def _key(r):
        v = r.get(sort)
        if sort == "name":
            return ("" if v is None else str(v).lower(), r.get("id") or "")
        return ("" if v is None else str(v), r.get("id") or "")
    tags.sort(key=_key, reverse=reverse)

    total = len(tags)
    page = tags[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    data = [{
        "id": r.get("id"),
        "instance_id": instance_id,
        "tag_id": r.get("external_id"),
        "name": r.get("name"),
        "status": r.get("status"),
        "created_at": r.get("created_at"),
        "updated_at": r.get("updated_at"),
    } for r in page]

    resp = {
        "data": data,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        }
    }
    _log("ok", instance_id, {"returned": len(data), "total": total})
    return resp

