def update_tag(instance_id, tag_id, body, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance=None, meta=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "ts": now,
            "endpoint": "update-tag",
            "instance_id": instance,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("n8n_request_logs.json", logs)

    # Validate input
    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", instance_id if isinstance(instance_id, str) else None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "instance_id is invalid")
    if not isinstance(tag_id, str) or not tag_id.strip():
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "tag_id is invalid")
    if not isinstance(body, dict) or set(body.keys()) - {"name"}:
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body is invalid")
    name = body.get("name")
    if not isinstance(name, str) or not name.strip():
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body.name is required and must be a non-empty string")
    name = name.strip()

    instances = _load("n8n_instances.json")
    assets = _load("n8n_assets_and_audit.json")

    # Auth / instance scope rule: must have active instance
    inst = next((x for x in instances if isinstance(x, dict) and x.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("status") != "active":
        _log("error", instance_id, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Instance is not active")

    # Principal resolution (ambient): must have at least one active principal in instance
    principals = _load("n8n_principals.json")
    has_principal = any(isinstance(p, dict) and p.get("instance_id") == instance_id and p.get("status") == "active" for p in principals)
    if not has_principal:
        _log("error", instance_id, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authorized principal available for this instance")

    if not isinstance(assets, list):
        assets = []

    # Find tag row by external_id
    tag_row = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("instance_id") == instance_id and a.get("asset_type") == "tag" and a.get("status") != "deleted" and a.get("external_id") == tag_id:
            tag_row = a
            break
    if not tag_row:
        _log("error", instance_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tag not found")

    # Uniqueness: (instance_id, asset_type='tag', name) among non-deleted tags
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a is tag_row:
            continue
        if a.get("instance_id") == instance_id and a.get("asset_type") == "tag" and a.get("status") != "deleted":
            if isinstance(a.get("name"), str) and a.get("name") == name:
                _log("error", instance_id, {"code": "CONFLICT"})
                return _err("CONFLICT", "A tag with this name already exists in the instance")

    # Idempotent update
    if tag_row.get("name") == name:
        _log("ok", instance_id, {"idempotent": True})
        return {"data": tag_row, "meta": {"idempotent": True}}

    tag_row["name"] = name
    tag_row["updated_at"] = now
    _save("n8n_assets_and_audit.json", assets)

    _log("ok", instance_id)
    return {"data": tag_row}

