            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-tag"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"n8n_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "instance_id": instance_id,
            "tag_id": tag_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error
        })
        _save("n8n_request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id is invalid", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if not isinstance(tag_id, str) or tag_id.strip() == "":
            e = _err("VALIDATION_ERROR", "tag_id is required", tag_id=tag_id)
            _append_log("error", e["error"])
            return e

        instances = _load("n8n_instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if r.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
            _append_log("error", e["error"])
            return e
        if inst.get("status") != "active":
            e = _err("UNAUTHORIZED", "Active instance required.", rule="active_instance_required", instance_id=instance_id)
            _append_log("error", e["error"])
            return e

        assets = _load("n8n_assets_and_audit.json")
        if not isinstance(assets, list):
            assets = []

        tag = next((a for a in assets if a.get("instance_id") == instance_id and a.get("asset_type") == "tag" and a.get("status") != "deleted" and (a.get("external_id") == tag_id or a.get("id") == tag_id)), None)
        if not tag:
            e = _err("NOT_FOUND", "Tag not found.", instance_id=instance_id, tag_id=tag_id)
            _append_log("error", e["error"])
            return e

        # If there are workflow_tag relations referencing this tag, allow delete by cascade marking relations deleted.
        # (Real n8n may allow; schema doesn't forbid; avoid CONFLICT unless needed.)
        wtag_rows = [a for a in assets if a.get("instance_id") == instance_id and a.get("asset_type") == "workflow_tag" and a.get("status") != "deleted" and a.get("tag_id") == (tag.get("external_id") or tag_id)]
        for rel in wtag_rows:
            rel["status"] = "deleted"
            rel["updated_at"] = _now()

        transitions = {"active": ["disabled", "deleted"], "disabled": ["active", "deleted"], "deleted": []}
        cur = tag.get("status")
        if cur not in transitions:
            e = _err("INVALID_TRANSITION", "Tag has invalid current status.", tag_id=tag_id, status=cur)
            _append_log("error", e["error"])
            return e
        if "deleted" not in transitions[cur]:
            e = _err("INVALID_TRANSITION", "Cannot delete tag from current state.", tag_id=tag_id, from_status=cur, to_status="deleted")
            _append_log("error", e["error"])
            return e

        tag["status"] = "deleted"
        tag["updated_at"] = _now()
        _save("n8n_assets_and_audit.json", assets)

        _append_log("ok", None)
        return {"tag_id": tag.get("external_id") or tag.get("id"), "deleted": True, "status": tag.get("status"), "updated_at": tag.get("updated_at")}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected error while deleting tag.", detail=str(ex))
        try:
            _append_log("error", e["error"])
        except Exception:
            pass
        return e

def get_workflow_tags(instance_id, workflow_id, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance=None, meta=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "ts": now,
            "endpoint": "get-workflow-tags",
            "instance_id": instance,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("n8n_request_logs.json", logs)

    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", instance_id if isinstance(instance_id, str) else None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "instance_id is invalid")
    if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workflow_id is invalid")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name"):
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort is invalid")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "order is invalid")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                _log("error", instance_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("neg")
        except Exception:
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    instances = _load("n8n_instances.json")
    workflows = _load("n8n_workflows.json")
    assets = _load("n8n_assets_and_audit.json")

    inst = next((x for x in instances if isinstance(x, dict) and x.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("status") != "active":
        _log("error", instance_id, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Instance is not active")

    principals = _load("n8n_principals.json")
    has_principal = any(isinstance(p, dict) and p.get("instance_id") == instance_id and p.get("status") == "active" for p in principals)
    if not has_principal:
        _log("error", instance_id, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authorized principal available for this instance")

    wf = next((w for w in workflows if isinstance(w, dict) and w.get("id") == workflow_id and w.get("instance_id") == instance_id and w.get("status") != "deleted"), None)
    if not wf:
        _log("error", instance_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workflow not found")

    if not isinstance(assets, list):
        assets = []

    # Collect tag_ids from workflow_tag relations
    tag_ids = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("instance_id") == instance_id and a.get("asset_type") == "workflow_tag" and a.get("status") != "deleted" and a.get("workflow_id") == workflow_id:
            tid = a.get("tag_id")
            if isinstance(tid, str) and tid:
                tag_ids.append(tid)

    # Join to tag assets by external_id
    tags = []
    tag_set = set(tag_ids)
    if tag_set:
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("instance_id") == instance_id and a.get("asset_type") == "tag" and a.get("status") != "deleted":
                if a.get("external_id") in tag_set:
                    tags.append(a)

    def _key(v):
        if sort in ("created_at", "updated_at"):
            x = v.get(sort)
            return (x is None, x or "")
        if sort == "name":
            x = v.get("name")
            return (x is None, (x or "").lower(), x or "")
        return ""

    reverse = (order == "desc")
    tags.sort(key=_key, reverse=reverse)

    total = len(tags)
    page = tags[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{start + limit}".encode("utf-8")).decode("utf-8")

    _log("ok", instance_id, {"total": total, "returned": len(page)})
    return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "limit": limit, "cursor": cursor, "sort": sort, "order": order}}

def update_workflow_tags(instance_id, workflow_id, body, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance=None, meta=None):
        logs = _load("n8n_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "ts": now,
            "endpoint": "update-workflow-tags",
            "instance_id": instance,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("n8n_request_logs.json", logs)

    if not isinstance(instance_id, str) or not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", instance_id if isinstance(instance_id, str) else None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "instance_id is invalid")
    if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workflow_id is invalid")
    if not isinstance(body, dict) or set(body.keys()) - {"tag_ids"}:
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body is invalid")
    tag_ids = body.get("tag_ids")
    if not isinstance(tag_ids, list):
        _log("error", instance_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "body.tag_ids must be an array")
    for tid in tag_ids:
        if not isinstance(tid, str) or not tid.strip():
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "All tag_ids must be non-empty strings")
    # de-dupe but preserve order
    seen = set()
    tag_ids_norm = []
    for tid in tag_ids:
        tid = tid.strip()
        if tid not in seen:
            seen.add(tid)
            tag_ids_norm.append(tid)

    instances = _load("n8n_instances.json")
    workflows = _load("n8n_workflows.json")
    assets = _load("n8n_assets_and_audit.json")

    inst = next((x for x in instances if isinstance(x, dict) and x.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("status") != "active":
        _log("error", instance_id, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Instance is not active")

    principals = _load("n8n_principals.json")
    active_principals = [p for p in principals if isinstance(p, dict) and p.get("instance_id") == instance_id and p.get("status") == "active"]
    if not active_principals:
        _log("error", instance_id, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authorized principal available for this instance")

    wf = next((w for w in workflows if isinstance(w, dict) and w.get("id") == workflow_id and w.get("instance_id") == instance_id and w.get("status") != "deleted"), None)
    if not wf:
        _log("error", instance_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workflow not found")

    if not isinstance(assets, list):
        assets = []

    # Ensure all referenced tags exist and are not deleted
    tags_by_external = {}
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("instance_id") == instance_id and a.get("asset_type") == "tag" and a.get("status") != "deleted":
            eid = a.get("external_id")
            if isinstance(eid, str) and eid:
                tags_by_external[eid] = a
    missing = [tid for tid in tag_ids_norm if tid not in tags_by_external]
    if missing:
        _log("error", instance_id, {"code": "NOT_FOUND", "missing_tag_ids": missing})
        return _err("NOT_FOUND", "One or more tags were not found", missing_tag_ids=missing)

    # Current relations
    current_rel_rows = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("instance_id") == instance_id
        and a.get("asset_type") == "workflow_tag"
        and a.get("status") != "deleted"
        and a.get("workflow_id") == workflow_id
        and isinstance(a.get("tag_id"), str)
        and a.get("tag_id")
    ]
    current_set = set(a.get("tag_id") for a in current_rel_rows)
    desired_set = set(tag_ids_norm)

    to_remove = current_set - desired_set
    to_add = desired_set - current_set

    # Apply removals (mark deleted for auditability)
    changed = False
    for a in current_rel_rows:
        if a.get("tag_id") in to_remove:
            a["status"] = "deleted"
            a["updated_at"] = now
            changed = True

    # Add new relations, enforce uniqueness (workflow_id, tag_id) via set logic
    def _new_id(prefix):
        # 18+ chars uppercase base36-ish
        import secrets, string
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    for tid in tag_ids_norm:
        if tid in to_add:
            assets.append({
                "id": _new_id("n8n_ast_"),
                "instance_id": instance_id,
                "asset_type": "workflow_tag",
                "external_id": None,
                "workflow_id": workflow_id,
                "project_id": None,
                "owner_principal_id": None,
                "name": None,
                "key": None,
                "value_encrypted": None,
                "credential_type": None,
                "data_encrypted": None,
                "schema": None,
                "execution_status": None,
                "started_at": None,
                "stopped_at": None,
                "execution_data": None,
                "tag_id": tid,
                "report": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            })
            changed = True

    if not changed:
        # Idempotent: return current associations
        tags = [tags_by_external[tid] for tid in tag_ids_norm if tid in tags_by_external]
        _log("ok", instance_id, {"idempotent": True, "count": len(tags)})
        return {"data": {"workflow_id": workflow_id, "tag_ids": tag_ids_norm, "tags": tags}, "meta": {"idempotent": True}}

    _save("n8n_assets_and_audit.json", assets)

    # Return updated associations (tags in same order as tag_ids_norm)
    tags = [tags_by_external[tid] for tid in tag_ids_norm if tid in tags_by_external]
    _log("ok", instance_id, {"count": len(tags), "added": len(to_add), "removed": len(to_remove)})
    return {"data": {"workflow_id": workflow_id, "tag_ids": tag_ids_norm, "tags": tags}, "meta": {"added": sorted(list(to_add)), "removed": sorted(list(to_remove))}}

def generate_audit(instance_id, project_id=None, workflow_id=None, include_asset_types=None, include_disabled=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0229000" if __import__("os").path.isdir("./environment_mix/0229000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request/audit logging (best-effort: tool must not raise)
    audit_file = "request_log.json"
    reqlog = _load(audit_file)
    if not isinstance(reqlog, list):
        reqlog = []

    def _log(status, credential_used=None, error_code=None):
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(reqlog)+1}",
            "endpoint": "generate-audit",
            "timestamp": _now,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
        }
        reqlog.append(row)
        _save(audit_file, reqlog)

    # Basic rate limit (per endpoint, rolling 60s) if request_log exists/used
    try:
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in reqlog[-2000:]:
            if isinstance(r, dict) and r.get("endpoint") == "generate-audit" and isinstance(r.get("timestamp"), str):
                if r["timestamp"] >= cutoff:
                    recent += 1
        if recent >= 60:
            _log("error", error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded for generate-audit (60 requests/min).")
    except Exception:
        # If log contains malformed timestamps etc., do not block; continue.
        pass

    # Validate inputs
    if not isinstance(instance_id, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a string.")
    if not re.match(r"^n8n_ins_[0-9A-Z]{18,}$", instance_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id is malformed.")

    if project_id is not None:
        if not isinstance(project_id, str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id must be a string.")
        if not re.match(r"^n8n_prj_[0-9A-Z]{18,}$", project_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id is malformed.")

    if workflow_id is not None:
        if not isinstance(workflow_id, str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workflow_id must be a string.")
        if not re.match(r"^n8n_wf_[0-9A-Z]{18,}$", workflow_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workflow_id is malformed.")

    if include_disabled is not None and not isinstance(include_disabled, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_disabled must be a boolean.")

    supported_asset_types = ["variable", "credential", "execution", "tag", "workflow_tag", "credential_schema"]
    if include_asset_types is not None:
        if not isinstance(include_asset_types, list) or any(not isinstance(x, str) for x in include_asset_types):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "include_asset_types must be an array of strings.")
        bad = [x for x in include_asset_types if x not in supported_asset_types]
        if bad:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "include_asset_types contains unsupported values.", unsupported=bad)

    # Scope consistency: if both provided, workflow must belong to project if workflow has a project_id.
    instances = _load("n8n_instances.json")
    if not isinstance(instances, list):
        instances = []
    instance = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not instance:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.")
    if instance.get("status") != "active":
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active n8n instance available for this request.")

    principals = _load("n8n_principals.json")
    if not isinstance(principals, list):
        principals = []
    # Ambient auth: pick any active owner/admin principal in this instance (must exist to authorize).
    caller = None
    for p in principals:
        if not isinstance(p, dict):
            continue
        if p.get("instance_id") != instance_id:
            continue
        if p.get("status") != "active":
            continue
        if p.get("role") in ("owner", "admin"):
            caller = p
            break
    if not caller:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You are not permitted to generate audits for this instance.")

    projects = _load("n8n_projects.json")
    if not isinstance(projects, list):
        projects = []
    if project_id is not None:
        prj = next((r for r in projects if isinstance(r, dict) and r.get("id") == project_id and r.get("instance_id") == instance_id and r.get("status") != "deleted"), None)
        if not prj:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Project not found in this instance.")

    workflows = _load("n8n_workflows.json")
    if not isinstance(workflows, list):
        workflows = []
    wf = None
    if workflow_id is not None:
        wf = next((r for r in workflows if isinstance(r, dict) and r.get("id") == workflow_id and r.get("instance_id") == instance_id and r.get("status") != "deleted"), None)
        if not wf:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Workflow not found in this instance.")
        if project_id is not None:
            wf_prj = wf.get("project_id")
            if wf_prj is not None and wf_prj != project_id:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Scope parameters are inconsistent: workflow_id does not belong to project_id.")

    # Determine audit scope workflow/project filters
    scope_project_id = project_id
    scope_workflow_id = workflow_id
    if scope_project_id is None and wf is not None and isinstance(wf.get("project_id"), str):
        # If caller scoped to workflow and that workflow belongs to a project, treat as within that project (for reporting).
        scope_project_id = wf.get("project_id")

    assets = _load("n8n_assets_and_audit.json")
    if not isinstance(assets, list):
        assets = []

    inc_types = include_asset_types if include_asset_types is not None else supported_asset_types
    include_disabled_flag = bool(include_disabled) if include_disabled is not None else False

    def _asset_in_scope(a):
        if a.get("instance_id") != instance_id:
            return False
        if a.get("asset_type") not in inc_types:
            return False
        if a.get("status") == "deleted":
            return False
        if not include_disabled_flag and a.get("status") == "disabled":
            return False
        if scope_project_id is not None:
            # assets may be associated with project_id (variables/credentials) or via workflow's project
            if a.get("project_id") != scope_project_id:
                # allow execution/workflow_tag/tag assets if workflow matches a workflow in the project scope
                if a.get("workflow_id"):
                    wrow = next((w for w in workflows if isinstance(w, dict) and w.get("id") == a.get("workflow_id") and w.get("instance_id") == instance_id and w.get("status") != "deleted"), None)
                    if not wrow or wrow.get("project_id") != scope_project_id:
                        return False
                else:
                    # tags/credential_schema without project_id are global; exclude when project-scoped
                    return False
        if scope_workflow_id is not None:
            # only include assets directly tied to workflow, except tags joined via workflow_tag which are represented separately
            if a.get("asset_type") in ("execution", "workflow_tag"):
                return a.get("workflow_id") == scope_workflow_id
            # for "tag" assets: include only if linked via workflow_tag for this workflow
            if a.get("asset_type") == "tag":
                return any(isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("asset_type") == "workflow_tag"
                           and r.get("status") != "deleted"
                           and r.get("workflow_id") == scope_workflow_id
                           and r.get("tag_id") == a.get("external_id")
                           for r in assets)
            # credentials/variables are not workflow-bound in this schema: exclude if workflow-scoped
            return False
        return True

    scoped_assets = [a for a in assets if isinstance(a, dict) and _asset_in_scope(a)]

    # Findings: simple deterministic checks based on stored metadata only (no secrets decrypted)
    findings = []
    counts_by_type = {t: 0 for t in supported_asset_types}
    disabled_count = 0

    for a in scoped_assets:
        at = a.get("asset_type")
        if at in counts_by_type:
            counts_by_type[at] += 1
        if a.get("status") == "disabled":
            disabled_count += 1

        if at == "credential":
            if not a.get("owner_principal_id"):
                findings.append({
                    "severity": "medium",
                    "type": "credential_missing_owner",
                    "message": "Credential has no owner_principal_id set.",
                    "asset_id": a.get("id"),
                    "external_id": a.get("external_id"),
                    "name": a.get("name"),
                })
            if not a.get("data_encrypted"):
                findings.append({
                    "severity": "high",
                    "type": "credential_missing_encrypted_data",
                    "message": "Credential is missing encrypted data payload.",
                    "asset_id": a.get("id"),
                    "external_id": a.get("external_id"),
                    "name": a.get("name"),
                })
        elif at == "variable":
            if not a.get("key"):
                findings.append({
                    "severity": "low",
                    "type": "variable_missing_key",
                    "message": "Variable asset missing key field.",
                    "asset_id": a.get("id"),
                    "external_id": a.get("external_id"),
                    "name": a.get("name"),
                })
            if not a.get("value_encrypted"):
                findings.append({
                    "severity": "high",
                    "type": "variable_missing_encrypted_value",
                    "message": "Variable is missing encrypted value payload.",
                    "asset_id": a.get("id"),
                    "key": a.get("key"),
                    "name": a.get("name"),
                })
        elif at == "execution":
            st = a.get("execution_status")
            if st in ("error", "crashed"):
                findings.append({
                    "severity": "medium",
                    "type": "execution_failed",
                    "message": f"Execution ended in status '{st}'.",
                    "asset_id": a.get("id"),
                    "external_id": a.get("external_id"),
                    "workflow_id": a.get("workflow_id"),
                })
            if st == "running":
                # Potentially long-running: if started_at exists and > 24h, flag
                try:
                    if isinstance(a.get("started_at"), str):
                        # Compare lexicographically for ISO Z; good enough here
                        day_ago = (datetime.datetime.utcnow() - datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"
                        if a["started_at"] <= day_ago:
                            findings.append({
                                "severity": "low",
                                "type": "execution_long_running",
                                "message": "Execution has been running for more than 24 hours (based on started_at).",
                                "asset_id": a.get("id"),
                                "external_id": a.get("external_id"),
                                "workflow_id": a.get("workflow_id"),
                                "started_at": a.get("started_at"),
                            })
                except Exception:
                    pass

    # Include workflow/project summary
    scoped_workflows = []
    if scope_workflow_id is not None:
        scoped_workflows = [w for w in workflows if isinstance(w, dict) and w.get("id") == scope_workflow_id and w.get("instance_id") == instance_id and w.get("status") != "deleted"]
    elif scope_project_id is not None:
        scoped_workflows = [w for w in workflows if isinstance(w, dict) and w.get("instance_id") == instance_id and w.get("status") != "deleted" and w.get("project_id") == scope_project_id]
    else:
        scoped_workflows = [w for w in workflows if isinstance(w, dict) and w.get("instance_id") == instance_id and w.get("status") != "deleted"]

    wf_counts = {
        "total": len(scoped_workflows),
        "active": sum(1 for w in scoped_workflows if w.get("status") == "active"),
        "inactive": sum(1 for w in scoped_workflows if w.get("status") == "inactive"),
        "draft": sum(1 for w in scoped_workflows if w.get("status") == "draft"),
    }

    report = {
        "generated_at": _now,
        "instance_id": instance_id,
        "scope": {
            "project_id": project_id,
            "workflow_id": workflow_id,
        },
        "include_asset_types": inc_types,
        "include_disabled": include_disabled_flag,
        "summary": {
            "workflows": wf_counts,
            "assets": {
                "counts_by_type": {k: v for k, v in counts_by_type.items() if k in inc_types},
                "disabled_included": include_disabled_flag,
                "disabled_count": disabled_count if include_disabled_flag else None,
                "total_assets_included": len(scoped_assets),
            },
            "findings_total": len(findings),
            "findings_by_severity": {
                "high": sum(1 for f in findings if f.get("severity") == "high"),
                "medium": sum(1 for f in findings if f.get("severity") == "medium"),
                "low": sum(1 for f in findings if f.get("severity") == "low"),
            },
        },
        "findings": findings,
        "notes": [
            "Report is generated from locally stored metadata; encrypted fields are not decrypted.",
            "Audit reports are immutable after creation except for lifecycle status transitions.",
        ],
    }

    # Persist audit_report asset (immutable content)
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = int(time.time() * 1000)
        out = []
        while n > 0 and len(out) < 22:
            n, r = divmod(n, 36)
            out.append(alphabet[r])
        token = "".join(reversed(out)).rjust(18, "0")
        return f"{prefix}{token}"

    new_id = _gen_id("n8n_ast_")
    audit_row = {
        "id": new_id,
        "instance_id": instance_id,
        "asset_type": "audit_report",
        "external_id": None,
        "workflow_id": workflow_id,
        "project_id": project_id,
        "owner_principal_id": caller.get("id"),
        "name": "Security audit report",
        "key": None,
        "value_encrypted": None,
        "credential_type": None,
        "data_encrypted": None,
        "schema": None,
        "execution_status": None,
        "started_at": None,
        "stopped_at": None,
        "execution_data": None,
        "tag_id": None,
        "report": report,
        "status": "active",
        "created_at": _now,
        "updated_at": _now,
    }
    assets.append(audit_row)
    _save("n8n_assets_and_audit.json", assets)

    _log("success", credential_used={"principal_id": caller.get("id"), "role": caller.get("role")})

    return {
        "audit_report": audit_row,
        "report": report,
    }
